#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

#
# The owner's cloud and secret steps for M8's workroom previews (decision 258; docs/m8-preview-plan.md, Q11 and the
# 2026-11-28 note; docs/staging.md, "Setting up previews (M8)"). Run it yourself, at a terminal, from a checkout of main:
#
#   scripts/wizards/preview-setup.sh
#
# It does four things, each after you say yes:
#   1. You make a second Workers for Platforms dispatch namespace, for previews, on the content account (the second
#      account, which holds the content domain), in the dashboard. The wizard only asks its name.
#   2. It makes the ticket key, an Ed25519 key pair, on this machine with node's crypto, and sets the private half as
#      the API's secret PREVIEW_TICKET_KEY (`<kid>:<64 hex seed>`) on podster-api-staging with `wrangler secret put`,
#      read from a temporary file of mode 0600 that is deleted straight after (and by a trap on any exit). The seed is
#      never printed, never in a shell variable and never an argument.
#   3. It adds preview_namespace, preview_public_keys (`<kid>:<64 hex public key>`) and preview_access_origin to
#      scripts/deploy-content's configuration file, ~/.config/podster/content-deploy.json.
#   4. It runs scripts/deploy-content without --deploy (it only reads), then, if you say so, with --deploy, which asks
#      you to type the content domain.
#
# What it doesn't do: switch previews on. PREVIEWS "true" and CONTENT_PREVIEW_NAMESPACE under env.staging in
# apps/api/wrangler.jsonc are a code change, the architect's PR after this wizard, deployed by scripts/deploy-staging.
#
# It refuses unless wrangler is signed in to the staging account, the one in ~/.podster/cloudflare-account-id.staging,
# and never prints that ID or the content account's. It remembers the namespace's name and the key's ID and public
# half (none of them secret) in ~/.podster/preview-setup.staging, so a re-run offers them again.

PREVIEW_ACCOUNT_FILE="$HOME/.podster/cloudflare-account-id.staging"
PREVIEW_CONFIG_FILE="$HOME/.config/podster/content-deploy.json"
PREVIEW_TOKEN_FILE="$HOME/.config/podster/content-token"
# The application host, whose /preview-access page hands out tickets: APP_URL under env.staging in apps/api/wrangler.jsonc.
PREVIEW_ACCESS_ORIGIN="https://app-staging.podster.dev"
PREVIEW_SECRET="PREVIEW_TICKET_KEY"
PREVIEW_WORKER="podster-api-staging"
PREVIEW_REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
PREVIEW_TMP=""
STAGING_ACCOUNT=""

# The temporary folder, and the seed's file in it, go on every way out.
preview_cleanup() {
  if [[ -n "$PREVIEW_TMP" && -d "$PREVIEW_TMP" ]]; then rm -rf "$PREVIEW_TMP"; fi
  PREVIEW_TMP=""
}
trap preview_cleanup EXIT
trap 'preview_cleanup; exit 130' INT TERM HUP

# private_file PATH: a regular file, not a link, yours, mode 0600.
private_file() {
  [[ -f "$1" && ! -L "$1" ]] && [[ -n "$(find "$1" -maxdepth 0 -user "$(id -u)" -perm 0600 2>/dev/null)" ]]
}

# wr ARGS...: the API's pinned wrangler, from apps/api, on the staging account.
wr() {
  (cd "$PREVIEW_REPO/apps/api" && CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT" npx --no-install wrangler "$@")
}

# secret_names: the API Worker's secret names on staging, one a line. Fails if the list can't be read.
secret_names() {
  local out
  out=$(wr secret list --format json --env staging 2>/dev/null) || return 1
  jq -er 'if type == "array" then .[].name else error("not a list") end' <<<"$out" 2>/dev/null
}

# A namespace name both readers take: deploy-content's pattern, which is narrower than the API's (no `_`).
namespace_ok() { [[ "$1" =~ ^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$ ]]; }
# A key ID, as podster_core::preview_access::is_key_id reads one.
kid_ok() { [[ "$1" =~ ^[A-Za-z0-9_-]{1,64}$ ]]; }

usage() {
  cat <<EOF
Usage: scripts/wizards/preview-setup.sh [--help]

Sets up the cloud and secret side of M8's workroom previews on staging (decision 258): a preview dispatch namespace
on the content account, the ticket key $PREVIEW_SECRET on $PREVIEW_WORKER, and the content Worker's preview
configuration in $PREVIEW_CONFIG_FILE, then offers to run scripts/deploy-content.

It needs node, jq, npm ci in apps/api, wrangler signed in to the staging account named in $PREVIEW_ACCOUNT_FILE,
and the content deploy's configuration and token files (docs/content-deploy.md). It never prints an account ID or
the private key. Switching previews on is not part of it: that is the architect's PR afterwards.
EOF
}

run_wizard() {

if [[ "${1:-}" == "--help" || "${1:-}" == "-h" ]]; then
  usage
  return 0
fi
if (( $# )); then
  usage >&2
  return 2
fi

mkdir -p "$HOME/.podster"
ENV_FILE="$HOME/.podster/preview-setup.staging"
TOTAL_STAGES=6

banner "Workroom previews on staging (M8, decision 258)"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Check: tools, the staging account and the content deploy's files"
for tool in node jq npx find git; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool isn't installed."; return 1; }
done
if [[ ! -x "$PREVIEW_REPO/apps/api/node_modules/.bin/wrangler" ]]; then
  warn "apps/api has no wrangler. Run: cd apps/api && npm ci, then this wizard again."
  return 1
fi
# The deploy script must know the three preview keys (M8 step 8), or it refuses the configuration this wizard writes.
if ! grep -q 'preview_public_keys' "$PREVIEW_REPO/scripts/deploy-content"; then
  warn "This checkout's scripts/deploy-content doesn't read the preview configuration yet (M8 step 8, PR 646)."
  warn "Pull main once it has merged, then run this wizard again. Nothing was changed."
  return 1
fi
# The staging account: the owner's file, checked as scripts/deploy-staging checks it. The ID is never printed.
if ! private_file "$PREVIEW_ACCOUNT_FILE"; then
  warn "$PREVIEW_ACCOUNT_FILE must exist, be yours, a regular file and mode 0600 (docs/staging.md, \"Before you start\")."
  return 1
fi
STAGING_ACCOUNT=$(LC_ALL=C tr -d '\n' < "$PREVIEW_ACCOUNT_FILE")
if [[ ! "$STAGING_ACCOUNT" =~ ^[0-9a-f]{32}$ ]]; then
  STAGING_ACCOUNT=""
  warn "$PREVIEW_ACCOUNT_FILE must hold the account ID alone: 32 lowercase hex characters."
  return 1
fi
if [[ -n "${CLOUDFLARE_ACCOUNT_ID:-}" && "$CLOUDFLARE_ACCOUNT_ID" != "$STAGING_ACCOUNT" ]]; then
  warn "CLOUDFLARE_ACCOUNT_ID in this shell isn't the staging account in $PREVIEW_ACCOUNT_FILE. Unset it and run again."
  return 1
fi
if [[ -n "${CLOUDFLARE_ENV:-}" && "$CLOUDFLARE_ENV" != staging ]]; then
  warn "CLOUDFLARE_ENV is set to something other than staging. Unset it and run again."
  return 1
fi
say "Asking wrangler which accounts it is signed in to (the answer isn't shown)."
who=$(wr whoami 2>/dev/null || true)
if ! grep -qF "$STAGING_ACCOUNT" <<<"$who"; then
  who=""
  warn "wrangler isn't signed in to the staging account. Run: cd apps/api && npx wrangler login, then this wizard again."
  return 1
fi
who=""
# Listing the secrets shows the Worker exists, so `secret put` later can't make a stray empty Worker of another name.
if ! names=$(secret_names); then
  warn "Couldn't list $PREVIEW_WORKER's secrets, so the Worker may not exist on this account. Nothing was changed."
  return 1
fi
say "wrangler is signed in to the staging account, and $PREVIEW_WORKER is there."
# The content deploy's configuration: the four keys it has today, on the other account.
if ! private_file "$PREVIEW_CONFIG_FILE" || ! private_file "$PREVIEW_TOKEN_FILE"; then
  warn "$PREVIEW_CONFIG_FILE and $PREVIEW_TOKEN_FILE must exist, be yours, regular files and mode 0600"
  warn "(docs/content-deploy.md). Nothing was changed."
  return 1
fi
if ! jq -e 'type == "object" and ([ "account_id", "content_domain", "dispatch_namespace", "kv_namespace_id" ] - keys == [])
      and all(.[]; type == "string")' "$PREVIEW_CONFIG_FILE" >/dev/null 2>&1; then
  warn "$PREVIEW_CONFIG_FILE isn't the content deploy's configuration: it lacks account_id, content_domain,"
  warn "dispatch_namespace or kv_namespace_id. Nothing was changed."
  return 1
fi
if [[ "$(jq -r .account_id "$PREVIEW_CONFIG_FILE")" == "$STAGING_ACCOUNT" ]]; then
  warn "The content deploy's account_id is the staging account. The content account is the other one. Nothing was changed."
  return 1
fi
CONTENT_DOMAIN_NAME=$(jq -r .content_domain "$PREVIEW_CONFIG_FILE")
PRODUCTION_NAMESPACE=$(jq -r .dispatch_namespace "$PREVIEW_CONFIG_FILE")
case "${PREVIEW_ACCESS_ORIGIN#https://}" in
  "$CONTENT_DOMAIN_NAME" | *".$CONTENT_DOMAIN_NAME")
    warn "The application host is on the content domain. That is never allowed. Nothing was changed."
    return 1 ;;
esac
if ! grep -qF "\"APP_URL\": \"$PREVIEW_ACCESS_ORIGIN\"" "$PREVIEW_REPO/apps/api/wrangler.jsonc"; then
  warn "apps/api/wrangler.jsonc no longer names $PREVIEW_ACCESS_ORIGIN as staging's APP_URL. Tell the architect."
  return 1
fi
say "The content deploy's files are in place, on an account other than staging's."
# Stage 5 runs scripts/deploy-content, which refuses a checkout on a branch, behind main or with untracked files.
if git -C "$PREVIEW_REPO" symbolic-ref -q HEAD >/dev/null 2>&1 || [[ -n "$(git -C "$PREVIEW_REPO" status --porcelain 2>/dev/null)" ]]; then
  warn "This checkout is on a branch or has changes. Stage 5's scripts/deploy-content will refuse it; for that stage,"
  warn "run from a clean checkout detached at main's tip: git checkout --detach origin/main"
fi
pause "Press Enter to continue"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "Cloudflare, content account: the preview dispatch namespace"
say "Previews get a dispatch namespace of their own, never production's ($PRODUCTION_NAMESPACE)."
say "Sign in as a member of the content account, the one that holds $CONTENT_DOMAIN_NAME, not podster.dev's."
open_url "https://dash.cloudflare.com/?to=/:account/workers-for-platforms"
step "If Cloudflare asks which account, pick the one that holds $CONTENT_DOMAIN_NAME."
step "Workers for Platforms: check the list. If the preview namespace is already there, note its name and skip on."
step "Otherwise click Create namespace, name it podster-previews (or the name you choose below), and create it."
note "Lowercase letters, digits and -, starting and ending with a letter or digit, at most 63 characters."
[[ -n "$(_existing PREVIEW_NAMESPACE || true)" ]] || write_env PREVIEW_NAMESPACE "podster-previews"
while :; do
  ask PREVIEW_NAMESPACE "The preview namespace's name:" || { warn "no name read"; return 1; }
  if ! namespace_ok "$PREVIEW_NAMESPACE"; then
    warn "That isn't a name both the API and scripts/deploy-content take. Try again."
    continue
  fi
  if [[ "$PREVIEW_NAMESPACE" == "$PRODUCTION_NAMESPACE" ]]; then
    warn "That is production's namespace. Previews must have their own (decision 258)."
    continue
  fi
  break
done
write_env PREVIEW_NAMESPACE "$PREVIEW_NAMESPACE"
pause "Press Enter once the namespace $PREVIEW_NAMESPACE exists on the content account"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "The ticket key: $PREVIEW_SECRET on $PREVIEW_WORKER"
say "The API signs preview tickets and sessions with an Ed25519 key. This wizard makes the pair on this machine;"
say "the private half goes straight to wrangler from a file only you can read, and the file is then deleted."
say "The content Worker gets only the public half, by its key ID, in the next stage."
KEY_SET=no
if grep -qx "$PREVIEW_SECRET" <<<"$names"; then KEY_SET=yes; fi
OLD_PUBLIC="$(_existing PREVIEW_PUBLIC_KEY || true)"
MAKE_KEY=yes
if [[ "$KEY_SET" == yes ]]; then
  warn "$PREVIEW_WORKER already holds $PREVIEW_SECRET."
  if [[ -n "$OLD_PUBLIC" ]] && confirm "Keep it, and go on with its public half (${OLD_PUBLIC%%:*}) from the last run?"; then
    MAKE_KEY=no
  else
    warn "A new key replaces it at once: tickets and sessions signed with the old one stop working once the content"
    warn "Worker no longer holds its public half. The next stage offers to keep the old public half for that hour."
    confirm "Make a new key and replace $PREVIEW_SECRET?" || { warn "Nothing was changed."; return 1; }
  fi
fi
if [[ "$MAKE_KEY" == yes ]]; then
  PREVIEW_KID=""
  write_env PREVIEW_KID "staging-$(date -u +%Y%m%d)"
  while :; do
    ask PREVIEW_KID "The key's ID (kid):" || { warn "no key ID read"; return 1; }
    if ! kid_ok "$PREVIEW_KID"; then
      warn "A key ID is 1 to 64 letters, digits, - and _. Try again."
      continue
    fi
    if [[ -n "$OLD_PUBLIC" && "$PREVIEW_KID" == "${OLD_PUBLIC%%:*}" && "$KEY_SET" == yes ]]; then
      warn "That is the current key's ID. A new key needs a new ID, so a rotation can tell them apart."
      continue
    fi
    break
  done
  write_env PREVIEW_KID "$PREVIEW_KID"
  confirm "Set $PREVIEW_SECRET on $PREVIEW_WORKER now, as key $PREVIEW_KID?" || { warn "Nothing was set."; return 1; }
  PREVIEW_TMP=$(umask 077 && mktemp -d)
  # node writes `<kid>:<64 hex seed>` to the file, created new at mode 0600, and prints only `<kid>:<64 hex public>`.
  if ! NEW_PUBLIC=$(umask 077 && node -e '
    const { generateKeyPairSync } = require("node:crypto");
    const { writeFileSync } = require("node:fs");
    const [file, kid] = process.argv.slice(1);
    const { publicKey, privateKey } = generateKeyPairSync("ed25519");
    const seed = Buffer.from(privateKey.export({ format: "jwk" }).d, "base64url");
    const pub = Buffer.from(publicKey.export({ format: "jwk" }).x, "base64url");
    if (seed.length !== 32 || pub.length !== 32) process.exit(1);
    writeFileSync(file, `${kid}:${seed.toString("hex")}`, { mode: 0o600, flag: "wx" });
    seed.fill(0);
    process.stdout.write(`${kid}:${pub.toString("hex")}`);
  ' -- "$PREVIEW_TMP/key" "$PREVIEW_KID"); then
    preview_cleanup
    warn "node couldn't make the key. Nothing was set."
    return 1
  fi
  if [[ ! "$NEW_PUBLIC" =~ ^[A-Za-z0-9_-]{1,64}:[0-9a-f]{64}$ ]] || ! private_file "$PREVIEW_TMP/key"; then
    preview_cleanup
    warn "The key didn't come out in its form. Nothing was set."
    return 1
  fi
  if wr secret put "$PREVIEW_SECRET" --env staging < "$PREVIEW_TMP/key" >/dev/null 2>"$PREVIEW_TMP/err"; then
    preview_cleanup
    printf '  %s✓ set%s %s on %s\n' "$GREEN" "$RESET" "$PREVIEW_SECRET" "$PREVIEW_WORKER"
  else
    # Why, from wrangler's stderr, with anything long enough to be a key, a token or an ID masked.
    tail -n 10 "$PREVIEW_TMP/err" | sed -E -e 's/[A-Za-z0-9_-]{32,}/[masked]/g' -e 's/^/        | /' >&2 || true
    preview_cleanup
    warn "wrangler couldn't set $PREVIEW_SECRET. The key made for it is gone; run this wizard again to make another."
    return 1
  fi
  write_env PREVIEW_PUBLIC_KEY "$NEW_PUBLIC"
else
  NEW_PUBLIC="$OLD_PUBLIC"
  OLD_PUBLIC=""
fi
if names=$(secret_names) && grep -qx "$PREVIEW_SECRET" <<<"$names"; then
  note "  ✓ $PREVIEW_WORKER lists $PREVIEW_SECRET (by name; its value can't be read back)"
else
  warn "$PREVIEW_WORKER doesn't list $PREVIEW_SECRET. Check with: cd apps/api && npx wrangler secret list --env staging"
fi
pause "Press Enter to continue"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "The content Worker's preview configuration"
say "scripts/deploy-content reads three more keys from $PREVIEW_CONFIG_FILE, all three or none."
say "None is a secret: a namespace's name, public keys, and the application host."
PUBLIC_KEYS="$NEW_PUBLIC"
CURRENT_KEYS=$(jq -r '.preview_public_keys // ""' "$PREVIEW_CONFIG_FILE")
# A rotation: the content Worker keeps the old public half for an hour, the longest a session lives.
if [[ -n "$OLD_PUBLIC" && "$CURRENT_KEYS" == *"$OLD_PUBLIC"* && "${OLD_PUBLIC%%:*}" != "${NEW_PUBLIC%%:*}" ]]; then
  if confirm "Keep the old public key (${OLD_PUBLIC%%:*}) beside the new one for the next hour?"; then
    PUBLIC_KEYS="$NEW_PUBLIC,$OLD_PUBLIC"
    note "After an hour, run this wizard again and keep the key, which writes the new public key alone; then deploy."
  fi
fi
say "It will write:"
note "  preview_namespace:     $PREVIEW_NAMESPACE"
note "  preview_public_keys:   key ID(s) $(tr ',' '\n' <<<"$PUBLIC_KEYS" | cut -d: -f1 | paste -sd ' ' -)"
note "  preview_access_origin: $PREVIEW_ACCESS_ORIGIN"
note "The four keys already there are kept as they are."
confirm "Write them to $PREVIEW_CONFIG_FILE?" || { warn "The configuration wasn't changed."; return 1; }
config_next=$(jq --arg n "$PREVIEW_NAMESPACE" --arg k "$PUBLIC_KEYS" --arg o "$PREVIEW_ACCESS_ORIGIN" \
  '. + { preview_namespace: $n, preview_public_keys: $k, preview_access_origin: $o }' "$PREVIEW_CONFIG_FILE")
# Written in place, so the file keeps its mode, owner and inode, as deploy-content requires.
printf '%s\n' "$config_next" > "$PREVIEW_CONFIG_FILE"
config_next=""
printf '  %s✓ wrote%s the three preview keys → %s\n' "$GREEN" "$RESET" "$PREVIEW_CONFIG_FILE"
pause "Press Enter to continue"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Deploy the content Worker with previews"
say "First scripts/deploy-content without --deploy: it only reads, and checks the preview namespace exists."
if confirm "Run the report now?"; then
  # CLOUDFLARE_ACCOUNT_ID is passed so deploy-content's own check refuses a configuration on the staging account.
  if CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT" "$PREVIEW_REPO/scripts/deploy-content" --token-file "$PREVIEW_TOKEN_FILE" --config-file "$PREVIEW_CONFIG_FILE"; then
    say "The report passed."
    say "With --deploy it deploys the content Worker with the binding PREVIEW_APPS and its two preview variables,"
    say "and asks you to type the content domain to confirm. A deploy replaces the running content Worker."
    if confirm "Deploy the content Worker now?"; then
      if CLOUDFLARE_ACCOUNT_ID="$STAGING_ACCOUNT" "$PREVIEW_REPO/scripts/deploy-content" --token-file "$PREVIEW_TOKEN_FILE" --config-file "$PREVIEW_CONFIG_FILE" --deploy; then
        say "Deployed. Its checks after the deploy are above."
      else
        warn "The deploy didn't finish; its output above says why."
        SKIPPED+=("the content Worker's deploy: scripts/deploy-content --token-file $PREVIEW_TOKEN_FILE --config-file $PREVIEW_CONFIG_FILE --deploy")
      fi
    else
      SKIPPED+=("the content Worker's deploy: scripts/deploy-content --token-file $PREVIEW_TOKEN_FILE --config-file $PREVIEW_CONFIG_FILE --deploy")
    fi
  else
    warn "The report refused; its output above says why. Nothing was deployed."
    SKIPPED+=("scripts/deploy-content's report, then its --deploy, once the report's problem is fixed")
  fi
else
  SKIPPED+=("scripts/deploy-content --token-file $PREVIEW_TOKEN_FILE --config-file $PREVIEW_CONFIG_FILE, then with --deploy")
fi
pause "Press Enter to continue"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Hand-off: switching previews on is the architect's PR"
say "Previews stay off until apps/api/wrangler.jsonc sets, under env.staging:"
note "  \"PREVIEWS\": \"true\","
note "  \"CONTENT_PREVIEW_NAMESPACE\": \"$PREVIEW_NAMESPACE\","
say "That is a code change, reviewed and deployed with scripts/deploy-staging, not part of this wizard."
say "Tell the architect, none of it secret:"
note "  the preview namespace is $PREVIEW_NAMESPACE; $PREVIEW_SECRET is set as key ${NEW_PUBLIC%%:*};"
note "  the content Worker was deployed with previews, or not yet (see below)."
pause "Press Enter to finish"

NEW_PUBLIC=""
OLD_PUBLIC=""
STAGING_ACCOUNT=""
finish
}

run_wizard "$@"; exit
